    filepath = line.strip()
    if not filepath:
        continue

    try:
        for jsonline in open(filepath, errors="replace"):
            jsonline = jsonline.strip()
            if not jsonline:
                continue
            try:
                j = json.loads(jsonline)
                t = j.get("type")
                ts = j.get("timestamp", "")

                if t == "assistant":
                    m = j.get("message", {})
                    c = m.get("content", "")

                    content_text = ""
                    if isinstance(c, list):
                        for block in c:
                            if isinstance(block, dict) and block.get("type") == "text":
                                content_text = block.get("text", "")
                                break
                    elif isinstance(c, str):
                        content_text = c

                    # Parse JSON response
                    if "{" in content_text and "offences" in content_text:
                        try:
                            # Extract JSON
                            start = content_text.find("{")
                            end = content_text.rfind("}") + 1
                            json_str = content_text[start:end]
                            resp = json.loads(json_str)

                            for offence in resp.get("offences", []):
                                law = offence.get("law")
                                why = offence.get("why", "")
                                if law:
                                    law_counts[law] = law_counts.get(law, 0) + 1
                                    if len(offence_quotes) < 10:
                                        offence_quotes.append({
                                            'law': law,
                                            'quote': offence.get("quote", "")[:80],
                                            'why': why[:80],
                                            'date': ts[:10]
                                        })

                            if ts:
                                latest_dates.append(ts[:10])
                        except:
                            pass
            except:
                pass
    except:
        pass

